--- old
+++ new
@@ -21,2 +21,3 @@
 def _linear_score(value: float, best: float, worst: float) -> float:
+    """Map value linearly to [0,100], best→100, worst→0."""
     if best == worst:
@@ -28,2 +29,3 @@
 def _log_score(value: float, best: float, worst: float) -> float:
+    """Log-scale score where best→100, worst→0. Works for both higher-is-better (best>worst) and lower-is-better (best<worst)."""
     if value <= 0 or best <= 0 or worst <= 0:
@@ -121,3 +123,3 @@
     def _value_score(result:

--- old
+++ new
@@ -137,7 +137,6 @@
             }
-            weighted_scores = {
-                k: v for k, v in scores.items() if self.weights.get(k, 0.0) > 0
-            }
-            r.composite_score = self._weighted_harmonic_mean(weighted_scores)
-
+        weighted_scores = {
+            k: v for k, v in scores.items() if self.weights.get(k, 0.0) > 0
+        }
+        r.composite_score = self._weighted_harmonic_mean(weighted_scores)
         # 4. Sort and assign ranks
@@ -147,3 +

--- old
+++ new
@@ -276,5 +276,6 @@
         if current_ratio is not None:
+            # Use triangular scoring: peak at 2.0, declining on both sides
             if current_ratio > 0:
                 weighted_scores.append(
-                    (_linear_score(current_ratio, best=3.0, worst=0.5), CURRENT_RATIO_WEIGHT)
+                    (_triangular_score(current_ratio, low=0.5, optimal=2.0, high=5.0), CURRENT_RATIO_WEIGHT)
                 )
